const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    function nextInt() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        let res = 0;
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            res = res * 10 + (input.charCodeAt(pos) - 48);
            pos++;
        }
        return res;
    }

    const n = nextInt();
    if (n === null) return;

    const a = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        a[i] = nextInt();
    }

    a.sort();

    let ans = 0;
    for (let k = n - 1; k >= 2; k--) {
        let i = 0;
        let j = k - 1;
        const target = a[k];
        while (i < j) {
            if (a[i] + a[j] > target) {
                ans += (j - i);
                j--;
            } else {
                i++;
            }
        }
    }

    console.log(ans);
}

main();
